import{_ as a,C as r,o as i,c as o,E as n,a2 as l}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"企业智能体身份平面应把可轮换断言、凭据租约与传播边界分开","description":"","frontmatter":{"title":"企业智能体身份平面应把可轮换断言、凭据租约与传播边界分开","date":"2026-08-09","column":"industry-architecture","category":"daily","summary":"文件型 Workload Identity 不应直接成为长期运行凭据。更稳健的身份平面在每次交换时重新读取权威断言，派生短期 Token，合并并发刷新并控制日志暴露；同时必须把 Token 如何传播到子进程和工具边界作为另一项独立治理。","item_id":"Q-20260809-02","source_research_object":"research/analysis/Q-20260809-02-rotating-assertion-short-lived-credential.md","source_reading_result":"research/reading/Q-20260809-02-workload-identity-exchange.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-09-rotating-assertion-short-lived-credential-cover-v2.jpg"},"headers":[],"relativePath":"zh/industry/2026-08-09-rotating-assertion-short-lived-credential.md","filePath":"zh/industry/2026-08-09-rotating-assertion-short-lived-credential.md","lastUpdated":1787407830000}'),d={name:"zh/industry/2026-08-09-rotating-assertion-short-lived-credential.md"};function s(h,e,c,u,p,b){const t=r("ArticleCover");return i(),o("div",null,[n(t,{image:"/assets/covers/daily-2026-08-09-rotating-assertion-short-lived-credential-cover-v2.jpg",kicker:"行业架构 · 每日研究",title:"企业智能体身份平面应把可轮换断言、凭据租约与传播边界分开",summary:"文件型 Workload Identity 不应直接成为长期运行凭据。更稳健的身份平面在每次交换时重新读取权威断言，派生短期 Token，合并并发刷新并控制日志暴露；同时必须把 Token 如何传播到子进程和工具边界作为另一项独立治理。",version:"Q-20260809-02",status:"Daily Runtime V5 · 2026-08-09",languageHref:"/en/industry/2026-08-09-rotating-assertion-short-lived-credential",languageLabel:"English"}),e[0]||(e[0]=l(' # 企业智能体身份平面应把可轮换断言、凭据租约与传播边界分开 <p>企业把智能体接入内部系统时，最危险的简化之一，是把“身份来源”和“执行凭据”当成同一个对象。一个文件型 JWT Assertion 可以代表 Workload Identity，但它不适合被直接复制到所有运行线程、工具进程和远程执行环境中长期使用。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p><strong>可靠的智能体身份平面至少要分开四层：权威身份来源、交换权限、短期执行凭据、下游传播策略。</strong></p><p>这四层解决不同问题：断言由谁提供和轮换；谁有权把断言换成凭据；凭据能使用多久；哪些执行上下文可以得到它。短期 Token 只能缩短泄露窗口，不能自动证明最小权限或子进程隔离。</p><p>本文唯一分析输入是 <code>Q-20260809-02</code> Research Object。Production 未重新研究所选 Commit 的其他调用链。</p><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h2><p>本文基于 <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-02-rotating-assertion-short-lived-credential.md" target="_blank" rel="noreferrer">Research Object — Rotating Assertion to Short-Lived Runtime Credential</a>。其证据入口是 <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-02-workload-identity-exchange.md" target="_blank" rel="noreferrer">Reading Result — Short-Lived Workload Identity Exchange</a>。</p><p>所选实现明确支持文件断言重读、短期凭据交换、缓存、提前刷新、并发请求合并、临时失败回退和 Token 日志脱敏。它没有证明 Queue 最初提出的“所有子进程凭据都被剥离”这一更广泛结论。</p><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>实现每次交换都会重新打开 Assertion 文件，而不是只在进程启动时读取一次。这使身份提供方可以轮换断言，而运行进程不必为了获得新身份材料而重启。</p><p>交换结果是短期 ChatGPT Access Token。Research Object 记录的实现边界包括：</p><ul><li>断言大小与输入格式校验；</li><li>生产端点的协议和网络策略约束；</li><li>30 秒请求超时；</li><li>最长一小时的可接受 Token 生命周期；</li><li>当前有效 Token 的进程内缓存；</li><li>提前刷新与被拒绝后的刷新；</li><li>多个并发消费者共享一次刷新；</li><li>主动刷新临时失败时，仍可使用尚未过期的缓存 Token；</li><li>Debug 输出中隐藏 Token 值。</li></ul><h2 id="控制面分层" tabindex="-1">控制面分层 <a class="header-anchor" href="#控制面分层" aria-label="Permalink to &quot;控制面分层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制层</th><th>主要对象</th><th>解决的问题</th><th>不能替代的控制</th></tr></thead><tbody><tr><td>身份来源</td><td>文件型 JWT Assertion</td><td>外部授权与轮换</td><td>不等于可直接调用业务 API</td></tr><tr><td>交换权限</td><td>Federation Rule + Token Endpoint</td><td>谁可派生执行凭据</td><td>不证明下游最小权限</td></tr><tr><td>凭据租约</td><td>短期 Access Token</td><td>缩短暴露时间、支持刷新</td><td>不证明子进程不会继承</td></tr><tr><td>传播策略</td><td>进程、MCP、Hook、Git、远程执行边界</td><td>决定谁实际收到凭据</td><td>必须单独实现和测试</td></tr></tbody></table><p>表格是 Research Center 对 Research Object 的架构综合。</p><h2 id="讨论" tabindex="-1">讨论 <a class="header-anchor" href="#讨论" aria-label="Permalink to &quot;讨论&quot;">​</a></h2><p>重新读取断言的价值在于把轮换权保留在权威来源。若进程启动后永久缓存原始断言，外部身份已经轮换，运行时却仍可能继续基于旧材料申请凭据。Pull-based Exchange 把“现在什么身份有效”延迟到真正需要交换时再确定。</p><p>并发刷新合并则处理另一个典型控制面问题：多个任务同时发现 Token 临近过期时，如果各自独立交换，会造成请求风暴和不一致错误。共享刷新状态让一个交换成为当前进程的刷新权威。</p><p>临时刷新失败后继续使用尚未过期 Token，是可用性与立即更新之间的明确取舍。它成立的前提不是“旧 Token 一定安全”，而是旧 Token 仍处于已签发的有限租约内；因此最大生命周期、服务端撤销和 Federation Policy 仍然重要。</p><p>最需要防止的误读是：短期凭据不等于完整隔离。一个只有十分钟寿命的 Token，如果被无差别注入所有子进程、日志、Hook 或远程 Shell，仍可能在租约内造成严重暴露。传播边界必须有独立证据。</p><h2 id="工程影响" tabindex="-1">工程影响 <a class="header-anchor" href="#工程影响" aria-label="Permalink to &quot;工程影响&quot;">​</a></h2><p>对企业智能体平台，运行状态应分别记录：</p><ul><li>Assertion 来源与最后读取时间；</li><li>Federation Rule / Audience / Subject 约束；</li><li>当前 Token 的签发与过期时间；</li><li>刷新是否进行中、是否使用临时回退；</li><li>Token 被授权传播到哪些消费者；</li><li>哪些子进程环境已显式剥离身份材料；</li><li>诊断日志是否发生脱敏。</li></ul><p>对 CodeFlowMu，凭据应在最窄消费边界注入，而不是成为全局环境变量。任何“子进程已隔离”的产品声明，都应有 Environment Construction、Hook、MCP、Git 和远程执行的具体测试支持。</p><h2 id="边界与不确定性" tabindex="-1">边界与不确定性 <a class="header-anchor" href="#边界与不确定性" aria-label="Permalink to &quot;边界与不确定性&quot;">​</a></h2><p>当前证据没有完整展示 Federation 服务端如何限制 Audience、Subject 和 Scope，也没有覆盖所有新 Crate 的调用方。进程内缓存仍意味着拥有该对象的进程可以读取当前 Bearer Token。</p><p>因此，本文支持的是“轮换断言到短期凭据”的交换机制，不支持把它扩展为“企业凭据边界已经完整闭合”。</p><h2 id="未来工作" tabindex="-1">未来工作 <a class="header-anchor" href="#未来工作" aria-label="Permalink to &quot;未来工作&quot;">​</a></h2><p>后续应验证：Token 在撤销后如何 fencing；多个进程共享同一轮换断言时如何避免跨进程刷新风暴；哪些子进程确实需要授权委托；以及每次传播是否形成可审计的 Delegation Receipt。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图把 Assertion File、Exchange Authority、Access Token Lease 和 Propagation Boundary 分开。橙色虚线区域明确标记当前证据尚未证明的子进程传播控制。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260809-02-rotating-assertion-short-lived-credential.md" target="_blank" rel="noreferrer">Research Object — Rotating Assertion to Short-Lived Runtime Credential</a>：本文唯一分析输入。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260809-02-workload-identity-exchange.md" target="_blank" rel="noreferrer">Reading Result — Short-Lived Workload Identity Exchange</a>：实现事实、限制与未决问题的追溯入口。</li></ol>',34))])}const g=a(d,[["render",s]]);export{m as __pageData,g as default};
